import{_ as n}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as o,c as s,o as t,af as a,b as d,w as r,a as l,G as h,ag as c}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const T=JSON.parse('{"title":"Data, Pretraining, and Scaling (Bridge)","description":"The engineering meaning of the Data → Pretraining → Base model chain — the capability ceiling freezes at pretraining, which explains the root of knowledge cutoff, the structure of vendor pricing tiers, and \\"why a given model is unreliable on your task\\"; training detail belongs to Learn LLM.","frontmatter":{"title":"Data, Pretraining, and Scaling (Bridge)","description":"The engineering meaning of the Data → Pretraining → Base model chain — the capability ceiling freezes at pretraining, which explains the root of knowledge cutoff, the structure of vendor pricing tiers, and \\"why a given model is unreliable on your task\\"; training detail belongs to Learn LLM.","domain":"tech","tags":["tech","model-lifecycle","bridge","pretraining","scaling"],"navOrder":13,"topicId":"data-pretraining-scaling","layer":"1","status":"bridge","nodeType":"concept","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/chapters/08-tinygpt"}],"prerequisites":["architecture"],"next":["appendices-model-lifecycle"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/01-model-lifecycle/data-pretraining-scaling.md","filePath":"tech/01-model-lifecycle/data-pretraining-scaling.md","lastUpdated":1788326832000}'),g={name:"tech/01-model-lifecycle/data-pretraining-scaling.md"};function p(u,e,f,m,b,v){const i=o("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<blockquote><p><strong>Group</strong>: 01 · Model Lifecycle (bridge group) | <strong>Exit of the group above</strong>: you can decide knowledge ownership and pick the lowest-complexity option for a need (00-map group) | <strong>Exit of this page</strong>: you can explain the root of knowledge cutoff, and use &quot;the capability ceiling freezes at pretraining&quot; to discipline model selection, freshness strategy, and version-upgrade regression <strong>Prerequisites</strong>: <a href="./architecture.html">Model Architecture (Bridge)</a> | <strong>Next</strong>: <a href="./post-training/">Post-training</a> (in-group subgroup); deep principles at <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a></p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p><strong>Lead with the answer</strong>: a base model&#39;s capability ceiling freezes the moment pretraining ends. The trade-offs among data mix, scale, and compute (scaling laws) decide &quot;what this model can and cannot do&quot;. This chain explains three application-level facts: the root of knowledge cutoff, the structure of vendor model tiers and pricing, and why a given model is unreliable on your task. This page covers only the engineering meaning of the chain; the from-scratch pretraining pipeline belongs to <a href="https://llm.zenheart.site/chapters/08-tinygpt" target="_blank" rel="noreferrer">Learn LLM chapter 8</a>.</p><h3 id="the-chain" tabindex="-1">The chain <a class="header-anchor" href="#the-chain" aria-label="Permalink to &quot;The chain&quot;">​</a></h3>',4)),(t(),d(c,null,{default:r(()=>[h(i,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20D%5B%22Data%20engineering%3Cbr%2F%3Ecollect%20%C2%B7%20clean%20%C2%B7%20dedupe%20%C2%B7%20mix%22%5D%20--%3E%20P%5B%22Pretraining%3Cbr%2F%3Enext-token%20objective%20%C2%B7%20massive%20compute%22%5D%0A%20%20%20%20P%20--%3E%20B%5B%22Base%20model%3Cbr%2F%3Ecapability%20ceiling%20freezes%20here%22%5D%0A%20%20%20%20B%20--%3E%20PT%5B%22Post-training%20(next%20stop%20in%20this%20group)%3Cbr%2F%3ESFT%20%C2%B7%20RLHF%20%C2%B7%20PEFT%22%5D%0A%20%20%20%20B%20-.-%3E%7Cdata%20cutoff%20%3D%20knowledge%20cutoff%7C%20K%5B%22knowledge%20cutoff%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="three-engineering-consequences" tabindex="-1">Three engineering consequences <a class="header-anchor" href="#three-engineering-consequences" aria-label="Permalink to &quot;Three engineering consequences&quot;">​</a></h3><ol><li><strong>The root of knowledge cutoff is this chain.</strong> The model&#39;s factual knowledge comes from the collection cutoff of the pretraining corpus; post-training and product wrapping change behavior, not the world knowledge in the weights. Time-sensitive facts must go through retrieval (<a href="./../04-grounding/rag.html">RAG</a>); the cutoff is an interface property to check, not a defect.</li><li><strong>Scaling laws are the structure of vendor tiers.</strong> Kaplan and Chinchilla established that &quot;loss falls predictably with parameters, data, and compute, and there is a compute-optimal balance between parameters and data&quot; (this page does not restate the exponents). Engineering translation: capability tiers are purchasable compute decisions, vendors slice that curve into tiered pricing — your selection is choosing a point on someone else&#39;s scaling curve.</li><li><strong>Data quality decides task reliability.</strong> How well your domain is represented and cleaned in the pretraining corpus decides out-of-the-box performance; if benchmark data leaks into the corpus (contamination), leaderboard scores inflate. A single leaderboard is not a selection basis — use your own evaluation set (<a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a>, <a href="./../08-production/evaluation.html">evaluation</a>).</li></ol><h2 id="_2-when-to-hop" tabindex="-1">2. When to Hop <a class="header-anchor" href="#_2-when-to-hop" aria-label="Permalink to &quot;2. When to Hop&quot;">​</a></h2><p>This page has no runnable artifact; route via this table:</p><table tabindex="0"><thead><tr><th>Symptom / question</th><th>Where to go</th><th>Why</th></tr></thead><tbody><tr><td>Want pretraining running from scratch (TinyGPT, checkpoints, loss curves)</td><td>Learn LLM <a href="https://llm.zenheart.site/chapters/08-tinygpt" target="_blank" rel="noreferrer">chapter 8</a></td><td>The canonical full pretraining pipeline</td></tr><tr><td>Why/when training goes unstable</td><td>Learn LLM <a href="https://llm.zenheart.site/chapters/06-training-stability" target="_blank" rel="noreferrer">chapter 6</a></td><td>Training-stability engineering</td></tr><tr><td>The original scaling-law accounts</td><td>The Kaplan / Chinchilla papers (see resource table)</td><td>Primary sources; this page keeps only conclusions</td></tr><tr><td>What to do about time-sensitive knowledge</td><td>This repo&#39;s <a href="./../04-grounding/rag.html">RAG</a></td><td>Fresh knowledge goes through retrieval, not weights</td></tr><tr><td>How to select models reliably</td><td>This repo&#39;s <a href="./../08-production/evaluation.html">evaluation</a> + the evals site</td><td>Leaderboards can be contaminated; build your own set</td></tr><tr><td>Whether to fine-tune new knowledge into weights</td><td>In-group <a href="./post-training/sft.html">SFT (Bridge)</a></td><td>The decision gate for touching weights</td></tr></tbody></table><h2 id="_3-principles" tabindex="-1">3. Principles <a class="header-anchor" href="#_3-principles" aria-label="Permalink to &quot;3. Principles&quot;">​</a></h2><p>One-paragraph positioning: pretraining runs the next-token objective over a massive corpus for enough steps; scaling laws are the empirical regularity of that pipeline, not physical law — they guide vendors&#39; training-budget allocation and reach you in the form of model tiers and pricing. Data-engineering detail (dedup, mixing, filtering) and training stability belong to Learn LLM chapters 6 and 8 (retrievedAt 2026-09-01). This repo&#39;s stopping point is &quot;the capability ceiling freezes at pretraining&quot;: not a value judgment, just the engineering fact that published weights cannot be edited.</p><h2 id="_4-engineering-decision-impact" tabindex="-1">4. Engineering Decision Impact <a class="header-anchor" href="#_4-engineering-decision-impact" aria-label="Permalink to &quot;4. Engineering Decision Impact&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Engineering decision</th><th>Judgment derived from this chain</th><th>Cost of the wrong expectation</th></tr></thead><tbody><tr><td>Model selection</td><td>The ceiling froze at pretraining; leaderboard scores may be inflated by contamination</td><td>Selecting by leaderboard; task performance disappoints after launch</td></tr><tr><td>Knowledge freshness strategy</td><td>The cutoff is a hard property; it does not vanish because you prompt harder</td><td>Expecting a recent model to &quot;surely know&quot; recent events</td></tr><tr><td>Version upgrades</td><td>A new version = new data + new pretraining; every engineering assumption can shift</td><td>Switching to latest without regression evaluation</td></tr><tr><td>Cost structure literacy</td><td>Tier pricing is a slice of the scaling curve</td><td>Confusing &quot;more expensive&quot; with &quot;better for my task&quot;</td></tr><tr><td>Domain reliability checks</td><td>Corpus representation decides out-of-the-box behavior</td><td>Assuming zero-shot reliability in a specialist domain without sample testing</td></tr></tbody></table><p>Maintenance rule (in place of runbooks): when Learn LLM chapters 6/8 change structure, re-verify this page&#39;s deep links and update <code>lastVerified</code>; specific cutoff dates and corpus composition of mainstream models are vendor disclosures — this page keeps no list; defer to each vendor&#39;s model card.</p><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><p>Four-level reading route:</p><table tabindex="0"><thead><tr><th>Level</th><th>What to read</th><th>Why this order</th></tr></thead><tbody><tr><td>Beginner</td><td>This page + the <a href="./index.html">group guide</a></td><td>Build the &quot;chain → three consequences&quot; map</td></tr><tr><td>Builder</td><td><a href="./../04-grounding/rag.html">RAG</a> + <a href="./../08-production/evaluation.html">evaluation</a></td><td>Wire cutoff and reliability into main-line solutions</td></tr><tr><td>Operator</td><td>The version-regression view of <a href="./../08-production/evaluation.html">evaluation</a></td><td>Run regression on every model upgrade</td></tr><tr><td>Researcher</td><td>Learn LLM chapters 6, 8 + the two scaling papers</td><td>Descend to the primary accounts of pretraining and scale</td></tr></tbody></table><h3 id="resource-table" tabindex="-1">Resource table <a class="header-anchor" href="#resource-table" aria-label="Permalink to &quot;Resource table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Level</th><th>Canonical URL</th><th>Supported claim</th><th>Next</th></tr></thead><tbody><tr><td>Learn LLM ch. 8 · TinyGPT</td><td>E</td><td><a href="https://llm.zenheart.site/chapters/08-tinygpt" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/08-tinygpt</a></td><td>From-scratch pretraining, overfitting, checkpoint and resume</td><td>Run one pretraining end to end</td></tr><tr><td>Learn LLM ch. 6 · Training stability</td><td>E</td><td><a href="https://llm.zenheart.site/chapters/06-training-stability" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/06-training-stability</a></td><td>Training stability is an engineering problem</td><td>Understand training diagnostics</td></tr><tr><td>Scaling Laws for Neural Language Models (Kaplan et al., 2020)</td><td>L4</td><td><a href="https://arxiv.org/abs/2001.08361" target="_blank" rel="noreferrer">https://arxiv.org/abs/2001.08361</a></td><td>The systematic quantification of loss vs parameters/data/compute power laws</td><td>Read the loss-vs-scale plots</td></tr><tr><td>Training Compute-Optimal LLMs (Chinchilla, Hoffmann et al., 2022)</td><td>L4</td><td><a href="https://arxiv.org/abs/2203.15556" target="_blank" rel="noreferrer">https://arxiv.org/abs/2203.15556</a></td><td>A compute-optimal balance exists between parameters and data</td><td>Compare against Kaplan</td></tr><tr><td>The evals site</td><td>E</td><td><a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">https://evals.zenheart.site/</a></td><td>The canonical sibling for evaluation method and release evidence</td><td>Build your own evaluation set</td></tr></tbody></table><p>(Learn LLM chapters verified via its chapter index; arXiv links are stable abs URLs; retrievedAt 2026-09-01.)</p><h3 id="active-falsification-and-open-questions" tabindex="-1">Active falsification and open questions <a class="header-anchor" href="#active-falsification-and-open-questions" aria-label="Permalink to &quot;Active falsification and open questions&quot;">​</a></h3><ul><li>Falsification entry: decisions that require concrete training-budget, data-volume, or corpus-mix estimation (e.g. compute planning for training your own model) belong to Learn LLM or an ML team, not this page — sink the claim instead of expanding here.</li><li>Open: public contamination-detection methods and model-card disclosure standards are not unified and not per-model verified here; let your own evaluation set decide selection.</li></ul><h3 id="where-learn-ai-stops-where-to-continue" tabindex="-1">Where learn-ai stops / where to continue <a class="header-anchor" href="#where-learn-ai-stops-where-to-continue" aria-label="Permalink to &quot;Where learn-ai stops / where to continue&quot;">​</a></h3><ul><li>Training data engineering and experimental method: Learn LLM chapters 6 and 8 — this repo stops here.</li><li>Supply fresh knowledge to a model: this repo&#39;s <a href="./../04-grounding/">04-grounding group</a>.</li><li>Next stop in this group: <a href="./post-training/">Post-training</a> (the engineering-decision bridges for SFT / RLHF / PEFT).</li></ul>',20))])}const x=n(g,[["render",p]]);export{T as __pageData,x as default};
